/*
 Wilayah Integrasi Administratif & Rayon Operasional 2026
 (Kota Tanjungpinang & Kabupaten Bintan)
*/
/*!40101 SET NAMES utf8 */;

DROP TABLE IF EXISTS `wilayah_operasional`;

CREATE TABLE `wilayah_operasional` (
    `kodewilayah` VARCHAR(10) NOT NULL,
    `wilayah` VARCHAR(150) NOT NULL,
    `kodearea` VARCHAR(10) NOT NULL,
    `namaarea` VARCHAR(150) NOT NULL,
    `kecamatan` VARCHAR(150) NOT NULL,
    `kelurahan_desa` TEXT NOT NULL,
    `cakupan_rayon` LONGTEXT,
    PRIMARY KEY (`kodewilayah`, `kodearea`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

